 15 | @theme {
 16 |   /* PRIMARY STRATEGY: OCEANIC */
 17 |   --color-oceanic-dark: #005B6D;      /* Primary brand, high contrast */
 18 |   --color-oceanic-accent: #007489;    /* Interactive elements */
 19 |   --color-oceanic-secondary: #218993; /* Secondary actions */
 20 |   --color-oceanic-subtle: #7A9FA7;    /* Muted text, borders */
 21 | 
 22 |   /* VERIFIED ACCENTS */
 23 |   --color-warm-gold: #D4C19C;         /* Premium highlights */
 24 |   --color-slate-teal: #4A6163;        /* Neutral complement */
 25 |   --color-liberty-blue: #2E4A62;      /* Federal aesthetic */
 26 |   --color-heritage-red: #8B3E2F;      /* Alert, emphasis */
 27 |   --color-frost-mint: #E2F0E9;        /* Success, subtle bg */
 28 | 
 29 |   /* UI FOUNDATION */
 30 |   --color-ink: #0F151B;               /* Primary text */
 31 |   --color-canvas: #FAF9F6;            /* Page background */
 32 |   --color-soft-smoke: #F0F0F0;        /* Subtle dividers */
 33 | 
 34 |   /* AIRY SPACING (FEDERAL SCALE) */
 35 |   --spacing-airy-sm: 2rem;            /* 32px - Compact sections */
 36 |   --spacing-airy-md: 4rem;            /* 64px - Standard vertical rhythm */
 37 |   --spacing-airy-lg: 6rem;            /* 96px - Generous breathing room */
 38 |   --spacing-airy-xl: 10rem;           /* 160px - Statement sections */
 39 |   --spacing-airy-2xl: 14rem;          /* 224px - Hero padding */
 40 |   --spacing-airy-massive: 20rem;      /* 320px - Ultra-premium spacing */
 41 | 
 42 |   /* TYPOGRAPHY SCALE (STRATEGY-2 INSPIRED) */
 43 |   --font-size-xs: 0.75rem;            /* 12px - Metadata */
 44 |   --font-size-sm: 0.9rem;             /* 14px - Label */
 45 |   --font-size-base: 1rem;             /* 16px - Body text */
 46 |   --font-size-lg: 1.125rem;           /* 18px - Lead paragraph */
 47 |   --font-size-xl: 1.25rem;            /* 20px - Subheading */
 48 |   --font-size-2xl: 1.5rem;            /* 24px - Section title */
 49 |   --font-size-3xl: 1.8rem;            /* 28px - Display text clamp min */
 50 |   --font-size-4xl: 2.5rem;            /* 40px - Hero title clamp min */
 51 |   --font-size-5xl: 3.2rem;            /* 51px - Display text max */
 52 |   --font-size-6xl: 5.5rem;            /* 88px - Hero title max */
 53 | 
 54 |   /* FONT FAMILIES */
 55 |   --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
 56 |   --font-serif: 'Georgia', 'Times New Roman', serif;
 57 |   --font-mono: 'SF Mono', 'Consolas', monospace;
 58 | }
 59 | 
 60 | /* Base resets & utilities */
 61 | body {
 62 |   font-family: var(--font-sans);
 63 |   color: var(--color-ink);
 64 |   background-color: var(--color-canvas);
 65 |   line-height: 1.5;
 66 |   -webkit-font-smoothing: antialiased;
 67 |   -moz-osx-font-smoothing: grayscale;
 68 |   overscroll-behavior: none;
 69 | }
 70 | 
 71 | @layer utilities {
 72 |   .section-padding {
 73 |     padding: 12rem 2rem;
 74 |   }
 75 |   
 76 |   .text-label {
 77 |     font-size: var(--font-size-sm);
 78 |     font-weight: 600;
 79 |     letter-spacing: 0.3em;
 80 |     text-transform: uppercase;
 81 |   }
 82 |   
 83 |   .display-text {
 84 |     font-size: clamp(1.8rem, 4.5vw, 3.2rem);
 85 |     line-height: 1.25;
 86 |     font-weight: 300;
 87 |     letter-spacing: -0.01em;
 88 |   }
 89 |   
 90 |   .hero-title {
 91 |     font-size: clamp(2.5rem, 9vw, 5.5rem);
 92 |     font-weight: 300;
 93 |     line-height: 1;
 94 |     letter-spacing: -0.04em;
 95 |   }
 96 | }
