 98 | /* Fluid.Glass / Brutalist Components */
 99 | .tech-border {
100 |   border: 1px solid rgba(15, 21, 27, 0.1); /* Based on ink */
101 | }
102 | .dark .tech-border,
103 | .dark.tech-border {
